'use strict';
(() => {
  const paths = {
    'panel-left':'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16"/>',
    'panel-right':'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M15 4v16"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',
    activity:'<path d="M3 12h4l3-7 4 14 3-7h4"/>',layers:'<path d="m12 3 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 16l9 5 9-5"/>',
    file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9l-6-6Zm0 0v6h6M8 13h8M8 17h5"/>',
    folder:'<path d="M3 7V5h6l2 2h10v12H3V7Z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1"/>',
    moon:'<path d="M20 14a8 8 0 0 1-10-10 8 8 0 1 0 10 10Z"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',
    ethernet:'<rect x="4" y="4" width="16" height="13" rx="2"/><path d="M8 17v3h8v-3M8 8v3M12 8v3M16 8v3"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',
    alert:'<path d="m12 3 10 17H2L12 3Z"/><path d="M12 9v4M12 16h.01"/>',
    speaker:'<rect x="6" y="3" width="12" height="18" rx="2"/><circle cx="12" cy="14" r="3"/><path d="M12 7h.01"/>',
    monitor:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M12 17v4M8 21h8"/>',
    switch:'<rect x="3" y="7" width="18" height="10" rx="2"/><path d="M7 11v2M11 11v2M15 11v2M18 11v2"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M12 19V5m-5 5 5-5 5 5"/>',
    play:'<path d="m8 4 12 8-12 8V4Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
    chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',target:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/>'
  };
  const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.target}</svg>`;
  const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const badge = (text,kind='neutral') => `<span class="state ${kind}"><i class="tiny-dot"></i>${esc(text)}</span>`;
  const sessions=[{id:'bench',name:'Validação de protocolos',location:'Bancada principal',protocols:ProtocolCatalog.demo(),running:false,isDemo:true}];
  let currentId='bench',selectedId='rtp',page='session',tab='protocols',filter='all',toastTimer;
  const app=document.getElementById('app'),main=document.getElementById('main'),inspector=document.getElementById('inspector');
  sessions[0].interfaceName='Ethernet';
  const current=()=>sessions.find(s=>s.id===currentId);
  const presence=p=>p.presence===null?'Não executado':p.presence?'Observado':'Não observado';
  const format=n=>n===null?'—':n.toLocaleString('pt-BR');
  function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));root.querySelectorAll('[data-leading]').forEach(el=>{if(!el.querySelector('svg'))el.insertAdjacentHTML('afterbegin',icon(el.dataset.leading))})}
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3500)}
  function renderSessions(){document.getElementById('sessions').innerHTML=sessions.map(s=>`<button class="session-button ${s.id===currentId?'selected':''}" data-session="${s.id}" ${s.id===currentId?'aria-current="true"':''}><i class="tiny-dot"></i><span>${esc(s.name)}</span><time>hoje</time></button>`).join('')}
  function context(){return `<div class="context-row"><label>${icon('ethernet')}<select id="interface-select" aria-label="Interface demonstrativa"><option ${current().interfaceName==='Ethernet'?'selected':''}>Ethernet</option><option ${current().interfaceName==='Ethernet USB'?'selected':''}>Ethernet USB</option></select></label><span>Captura passiva</span><span class="divider"></span><span>Modo local</span><span class="session-state"><i class="tiny-dot"></i>${current().running?'Simulação em execução':'Exemplo em pausa'}</span></div>`}
  function composer(){const available=ProtocolCatalog.definitions.filter(p=>!current().protocols.some(q=>q.id===p.id));return `<div class="composer-zone"><form id="protocol-form" class="composer"><label for="protocol-choice">Adicionar protocolo à análise</label><div class="composer-input-row"><select id="protocol-choice" name="protocol" aria-label="Protocolo do catálogo" ${available.length?'':'disabled'}>${available.length?'<option value="">Selecione um protocolo ou perfil…</option>': '<option value="">Catálogo completo nesta sessão</option>'}${available.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.family)}</option>`).join('')}</select><button class="send-button" aria-label="Adicionar protocolo" type="submit" ${available.length?'':'disabled'}>${icon('arrow')}</button></div><div class="composer-foot">${icon('layers')}<span>Catálogo de protocolos</span><span>·</span>${icon('ethernet')}<span>${esc(current().interfaceName)}</span></div><div class="form-error" id="protocol-error" role="alert" hidden></div></form><p class="composer-hint">Protótipo visual. As observações e métricas são fictícias.</p></div>`}
  function protocolTable(){if(!current().protocols.length)return '';const list=current().protocols.filter(p=>filter==='all'||p.state===filter);return `<div class="list-toolbar"><span>${list.length} protocolos / perfis</span><select class="filter-select" id="state-filter" aria-label="Filtrar protocolos">${['Todos os estados','Validado','Atenção','Inconclusivo','Não observado','Não executado'].map((s,i)=>`<option value="${i?s:'all'}" ${(i?s:'all')===filter?'selected':''}>${s}</option>`).join('')}</select></div>${list.length?`<table class="protocol-table"><thead><tr><th scope="col">Protocolo</th><th scope="col" class="address-col">Presença</th><th scope="col" class="optional">Pacotes</th><th scope="col">Análise do critério</th></tr></thead><tbody>${list.map(p=>`<tr class="${p.id===selectedId?'selected':''}"><td><button class="protocol-name" data-protocol="${p.id}" aria-label="Inspecionar ${esc(p.name)}"><span class="protocol-symbol">${icon(p.icon)}</span><span><strong>${esc(p.name)}</strong><small>${esc(p.family)}</small></span></button></td><td class="mono address-col">${presence(p)}</td><td class="mono optional">${format(p.packets)}</td><td>${badge(p.state,p.status)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h2>Nenhum protocolo neste estado</h2><p>Escolha outro filtro para consultar os protocolos da sessão.</p></div>'}`}
  function flows(){if(!current().isDemo)return '<div class="empty"><h2>Aguardando observações</h2><p>Os fluxos serão agrupados pelo protocolo identificado na captura.</p></div>';return `<div class="list-toolbar"><span>Evidências de fluxo · dados fictícios</span><span>Janela de 60 s</span></div>${[
    ['rtp','RTP / RTCP · Fluxo 01','192.168.10.20:5004 → 239.69.0.1:5004','2.997 pacotes · 3 lacunas de sequência'],
    ['ptp','PTPv2 · Domínio 0','192.168.10.10 → 224.0.1.129','UDP 319 / 320 · 360 mensagens'],
    ['mdns','mDNS / DNS-SD · Multicast','192.168.10.20 → 224.0.0.251:5353','124 mensagens de descoberta']
  ].map(([id,title,route,note])=>`<div class="protocol-row"><div><strong>${title}</strong><p class="mono">${route}</p><p>${note}</p></div><button class="icon-button" data-protocol="${id}" aria-label="Inspecionar fluxo ${title}">${icon('chevron')}</button></div>`).join('')}<p class="section-intro" style="margin-top:18px">Endereços identificam a evidência do fluxo. A análise pertence ao protocolo.</p>`}
  function events(){if(!current().isDemo)return '<div class="empty"><h2>Nenhum evento de protocolo</h2><p>Esta sessão ainda não tem observações.</p></div>';return `<div class="timeline">${[
    ['14:32:10','QDP · Janela encerrada','Nenhuma mensagem interpretável observada. Bloqueio não confirmado.'],
    ['14:31:42','RTP · Lacunas na sequência','Três lacunas no fluxo de exemplo. Causa inconclusiva sem contadores de descarte da captura.'],
    ['14:31:18','PTPv2 · Mensagens observadas','Sync e Follow_Up no domínio 0. Precisão de sincronismo não medida.'],
    ['14:31:10','IGMPv3 · Query observada','Query identificada no ponto de captura local.']
  ].map(([time,title,note])=>`<div class="event"><time>${time}</time><div class="event-body">${title}<p>${note}</p></div></div>`).join('')}</div>`}
  function renderMain(){const s=current();if(page==='session'){
    main.innerHTML=`<div class="page-heading"><div><div class="eyebrow">${icon('folder')} Laboratório AV <span>/</span> Sessão</div><h1>${esc(s.name)}</h1><p class="heading-sub">${esc(s.location)} · ${s.isDemo?'01 out. 2026, 14:31 · cenário de exemplo':'Nova sessão · sem observações'}</p></div><div class="heading-actions"><button class="button" data-action="report">${icon('file')}Relatório</button><button class="button primary" data-action="run">${icon(s.running?'pause':'play')}${s.running?'Pausar':'Simular'}</button></div></div>${context()}${s.protocols.length?`<div class="summary"><div><div class="summary-label">Protocolos / perfis</div><div class="summary-value">${s.protocols.length}<small>selecionados</small></div></div><div><div class="summary-label">Protocolos observados</div><div class="summary-value">${s.protocols.filter(p=>p.presence===true).length}<small>na janela</small></div></div><div><div class="summary-label">Janela de observação</div><div class="summary-value">${s.isDemo?'60':'—'}<small>${s.isDemo?'segundos':'não executada'}</small></div></div><div><div class="summary-label">Critérios em atenção</div><div class="summary-value">${s.protocols.filter(p=>p.status==='warn').length}<small>para revisar</small></div></div></div>${s.isDemo?`<div class="notice">${icon('alert')}<div><strong>RTP: lacunas de sequência observadas.</strong><p>Sem contadores de descarte da captura, não é possível atribuir as lacunas à rede.</p></div></div>`:''}`:`<div class="empty">${icon('layers')}<h2>Quais protocolos vamos analisar?</h2><p>Selecione protocolos no catálogo abaixo. Cada análise terá seus próprios critérios, métricas e evidências.</p></div>`}<div class="tabs" role="tablist" aria-label="Dados da sessão">${[['protocols','Protocolos'],['flows','Fluxos'],['events','Eventos']].map(([key,label])=>`<button role="tab" id="tab-${key}" aria-controls="session-panel" aria-selected="${tab===key}" class="tab ${tab===key?'active':''}" data-tab="${key}">${label}${key==='protocols'?`<span class="tab-count">${s.protocols.length}</span>`:''}</button>`).join('')}</div><section id="session-panel" role="tabpanel" aria-labelledby="tab-${tab}">${tab==='protocols'?protocolTable():tab==='flows'?flows():events()}</section>${composer()}`;
  }else if(page==='captures')main.innerHTML=`<div class="eyebrow">${icon('folder')} Laboratório AV</div><h1>Capturas</h1><p class="section-intro">Evidências organizadas por sessão, protocolo e janela de observação.</p><div class="empty">${icon('layers')}<h2>Suas evidências começam aqui.</h2><p>Captura e importação PCAPNG serão implementadas em uma próxima etapa. Este protótipo não contém pacotes reais.</p><button class="button" data-page="session">Voltar aos protocolos</button></div>`;
  else main.innerHTML=`<div class="eyebrow">${icon('folder')} Laboratório AV</div><h1>Relatórios</h1><p class="section-intro">Presença, critérios, métricas e limitações por protocolo.</p><div class="artifact">${icon('file')}<div><h3>${esc(s.name)}</h3><p>Prévia demonstrativa · ${s.protocols.length} protocolos / perfis</p></div><button class="button" data-action="report">Abrir prévia ${icon('chevron')}</button></div>`;
  hydrate(main)}
  function renderInspector(){const p=current().protocols.find(p=>p.id===selectedId);inspector.innerHTML=`<div class="inspector-top"><span>Detalhes do protocolo</span><button class="icon-button" data-action="inspector" aria-label="Fechar painel de detalhes">${icon('x')}</button></div>${p?`<div class="inspector-identity"><span class="protocol-symbol">${icon(p.icon)}</span><h2>${esc(p.name)}</h2><p>${esc(p.family)} · ${esc(p.version)}</p><span class="mono">${esc(p.transport)}</span></div><div class="section-label">Diagnóstico do protocolo</div><div class="diagnostic-line"><div class="diagnostic-head"><span>Presença na captura</span>${badge(presence(p),p.presence?'ok':'neutral')}</div><p>${p.presence===null?'Sem execução nesta sessão.':`${format(p.packets)} pacotes · janela fictícia de 60 s.`}</p></div><div class="diagnostic-line"><div class="diagnostic-head"><span>Resultado do critério</span>${badge(p.state,p.status)}</div><p>${esc(p.criterion)}</p></div><div class="section-label">Métricas e observações</div>${p.metrics.length?`<dl class="key-values">${p.metrics.map(([name,value])=>`<dt>${esc(name)}</dt><dd>${esc(value)}</dd>`).join('')}</dl>`:'<p class="section-intro">Nenhuma métrica disponível.</p>'}<div class="section-label">Contexto da análise</div><dl class="key-values"><dt>Interface</dt><dd>${esc(current().interfaceName)}</dd><dt>Método</dt><dd>Captura passiva</dd><dt>Visibilidade</dt><dd>Local</dd><dt>Janela</dt><dd>${p.presence===null?'Não executada':'60 s · exemplo'}</dd></dl><div class="section-label">Evidência e limites</div><div class="evidence"><div class="evidence-header">${icon('file')} Nota do protocolo</div><p>${esc(p.detail)}</p><p style="margin-top:8px">${esc(p.limit)}</p><p style="margin-top:8px">Dados demonstrativos, sem captura vinculada.</p></div><button class="button" data-action="report">${icon('file')} Ver resumo por protocolo</button>`:`<div class="empty">${icon('layers')}<h2>Selecione um protocolo</h2><p>Critérios, métricas e evidências aparecem aqui.</p></div>`}`}
  function render(){renderSessions();renderMain();renderInspector();document.getElementById('breadcrumb-session').textContent=current().name;document.getElementById('footer-context').textContent=current().interfaceName+' · modo local';document.querySelectorAll('.primary-nav [data-page]').forEach(b=>{const active=b.dataset.page===page;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}
  function selectProtocol(id){const p=current().protocols.find(p=>p.id===id);if(!p){const added=ProtocolCatalog.blank(id);if(!added)return;current().protocols.push(added);toast('Protocolo selecionado. Análise não executada.')}selectedId=id;page='session';tab='protocols';filter='all';app.classList.remove('inspector-hidden','mobile-nav');app.classList.add('inspector-open');render();syncInspectorToggle()}
  function syncInspectorToggle(){const visible=matchMedia('(max-width:980px)').matches?app.classList.contains('inspector-open'):!app.classList.contains('inspector-hidden');document.querySelector('[aria-label="Alternar painel de detalhes"]').setAttribute('aria-expanded',String(visible))}
  function reportText(){const s=current();return `NETTOOLS AV — ANÁLISE POR PROTOCOLO\nDEMONSTRAÇÃO — Dados fictícios. Não usar como prova técnica.\n\nSessão: ${s.name}\nPonto: ${s.location}\nInterface de exemplo: ${s.interfaceName}\nMétodo: captura passiva · visibilidade local\n\n${s.protocols.map(p=>`${p.name} | ${p.version}\n  Presença: ${presence(p)}\n  Janela: ${p.presence===null?'não executada':'60 s de exemplo'}\n  Critério: ${p.criterion}\n  Resultado: ${p.state}\n  Pacotes: ${format(p.packets)}\n${p.metrics.map(([k,v])=>`  ${k}: ${v}`).join('\n')}\n  Observação: ${p.detail}\n  Limitação: ${p.limit}`).join('\n\n')||'Nenhum protocolo selecionado.'}\n\nNão houve captura ou envio real de pacotes.\nDiagnósticos agrupados exclusivamente por protocolo.`}
  function searchResults(){const query=document.getElementById('search-input').value.trim().toLocaleLowerCase('pt-BR');const found=ProtocolCatalog.definitions.filter(p=>(p.name+' '+p.family+' '+p.version).toLocaleLowerCase('pt-BR').includes(query));document.getElementById('search-results').innerHTML=found.length?found.map(p=>`<button class="search-result" data-protocol="${p.id}"><strong>${esc(p.name)}</strong><span>${current().protocols.some(q=>q.id===p.id)?'Abrir análise':'Adicionar à sessão'} · ${esc(p.family)}</span></button>`).join(''):'<p>Nenhum protocolo encontrado no catálogo.</p>'}
  function openDialog(id){document.querySelectorAll('dialog[open]').forEach(d=>d.close());document.getElementById(id).showModal()}
  document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
    if(b.dataset.protocol){document.querySelectorAll('dialog[open]').forEach(d=>d.close());selectProtocol(b.dataset.protocol);return}
    if(b.dataset.session){currentId=b.dataset.session;selectedId=current().protocols[0]?.id||null;page='session';tab='protocols';filter='all';app.classList.remove('mobile-nav');render();return}
    if(b.dataset.page){page=b.dataset.page;app.classList.remove('mobile-nav');render();return}
    if(b.dataset.tab){tab=b.dataset.tab;renderMain();document.getElementById('tab-'+tab).focus();return}
    switch(b.dataset.action){
      case 'sidebar':app.classList.toggle(matchMedia('(max-width:680px)').matches?'mobile-nav':'sidebar-hidden');break;
      case 'inspector':app.classList.toggle(matchMedia('(max-width:980px)').matches?'inspector-open':'inspector-hidden');syncInspectorToggle();break;
      case 'theme':{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';b.innerHTML=icon(dark?'moon':'sun');break}
      case 'new':document.getElementById('new-form').reset();openDialog('new-dialog');break;
      case 'search':document.getElementById('search-input').value='';searchResults();openDialog('search-dialog');document.getElementById('search-input').focus();break;
      case 'close':b.closest('dialog')?.close();break;
      case 'run':current().running=!current().running;renderMain();toast(current().running?'Simulação iniciada. Nenhuma captura real será executada.':'Simulação em pausa.');break;
      case 'report':document.getElementById('report-text').textContent=reportText();openDialog('report-dialog');break;
      case 'download':{const url=URL.createObjectURL(new Blob([reportText()],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='nettools-av-protocolos-demonstracao.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Download do resumo por protocolo solicitado.');break}
    }
  });
  document.addEventListener('change',event=>{if(event.target.id==='state-filter'){filter=event.target.value;renderMain()}if(event.target.id==='interface-select'){current().interfaceName=event.target.value;render();toast('Interface de exemplo alterada.')}});
  document.getElementById('search-input').addEventListener('input',searchResults);
  document.getElementById('new-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.target);const name=String(data.get('sessionName')).trim(),location=String(data.get('location')).trim();if(!name||!location)return;currentId='session-'+Date.now();sessions.push({id:currentId,name,location,protocols:[],running:false,isDemo:false,interfaceName:'Ethernet'});selectedId=null;page='session';tab='protocols';filter='all';document.getElementById('new-dialog').close();render();toast('Sessão pronta para selecionar protocolos.');});
  document.addEventListener('submit',event=>{if(event.target.id!=='protocol-form')return;event.preventDefault();const id=document.getElementById('protocol-choice').value;if(!id){const el=document.getElementById('protocol-error');el.textContent='Selecione um protocolo no catálogo.';el.hidden=false;return}selectProtocol(id)});
  document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&['k','n'].includes(event.key.toLowerCase())){event.preventDefault();document.querySelector(`[data-action="${event.key.toLowerCase()==='k'?'search':'new'}"]`).click()}if(event.key==='Escape'){app.classList.remove('mobile-nav','inspector-open');syncInspectorToggle()}if(event.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const keys=['protocols','flows','events'];tab=keys[(keys.indexOf(tab)+(event.key==='ArrowRight'?1:2))%3];renderMain();document.getElementById('tab-'+tab).focus()}});
  window.addEventListener('resize',syncInspectorToggle);
  hydrate();render();syncInspectorToggle();
})();

